def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def min_swaps_to_sort(permutation, allowed_swaps):
    n = len(permutation)
    parent = list(range(n))
    rank = [0] * n

    # Create the graph
    for a, b in allowed_swaps:
        union(parent, rank, a-1, b-1)

    # Find connected components
    components = {}
    for i in range(n):
        root = find(parent, i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    # Calculate minimum swaps for each component
    min_swaps = 0
    for component in components.values():
        visited = [False] * len(component)
        for start in range(len(component)):
            if not visited[start]:
                cycle_length = 0
                current = start
                while not visited[current]:
                    visited[current] = True
                    current = component.index(permutation.index(permutation[component[current]] + 1) - 1)
                    cycle_length += 1
                if cycle_length > 1:
                    min_swaps += (cycle_length - 1)

    return min_swaps

